        Scanner sc = new Scanner(System.in);
        int r = sc.nextInt();
        int c = sc.nextInt();
        int[][] a = new int[r][c];
        for(int i = 0; i < r; i++) {
            for(int j = 0; j < c; j++) {
                a[i][j] = sc.nextInt();
            }
        }
        StringBuilder sb = new StringBuilder();
        String sep = "";
        for(int j = 0; j < c; j++) {
            sb.append(sep).append(a[0][j]);
            sep = " ";
        }
        for(int i = 1; i < r; i++) {
            sb.append(sep).append(a[i][c - 1]);
            sep = " ";
        }
        if(r > 1) {
            for(int j = c - 2; j >= 0; j--) {
                sb.append(sep).append(a[r - 1][j]);
                sep = " ";
            }
        }
        if(c > 1 && r > 2) {
            for(int i = r - 2; i >= 1; i--) {
                sb.append(sep).append(a[i][0]);
                sep = " ";
            }
        }
        System.out.println(sb.toString());
    }
}

