import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int r = sc.nextInt();
        int c = sc.nextInt();
        int[][] a = new int[r][c];
        for(int i = 0; i < r; i++) {
            for(int j = 0; j < c; j++) {
                a[i][j] = sc.nextInt();
            }
        }
        int top = 0;
        int bottom = r - 1;
        int left = 0;
        int right = c - 1;
        StringBuilder sb = new StringBuilder();
        String sep = "";
        while(top <= bottom && left <= right) {
            for(int j = left; j <= right; j++) {
                sb.append(sep).append(a[top][j]);
                sep = " ";
            }
            top++;
            for(int i = top; i <= bottom; i++) {
                sb.append(sep).append(a[i][right]);
                sep = " ";
            }
            right--;
            if(top <= bottom) {
                for(int j = right; j >= left; j--) {
                    sb.append(sep).append(a[bottom][j]);
                    sep = " ";
                }
                bottom--;
            }
            if(left <= right) {
                for(int i = top; i <= bottom; i++) {
                    sb.append(sep).append(a[i][left]);
                    sep = " ";
                }
                left++;
            }
        }
        System.out.println(sb.toString());
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int r = sc.nextInt();
        int c = sc.nextInt();
        int[][] a = new int[r][c];
        for(int i = 0; i < r; i++) {
            for(int j = 0; j < c; j++) {
                a[i][j] = sc.nextInt();
            }
        }
        boolean found = false;
        outer:
        for(int i = 0; i < r; i++) {
            for(int j = 0; j < c; j++) {
                boolean isRowMin = true;
                boolean isColMax = true;
                for(int k = 0; k < c; k++) {
                    if(a[i][k] < a[i][j]) {
                        isRowMin = false;
                    }
                }
                for(int k = 0; k < r; k++) {
                    if(a[k][j] > a[i][j]) {
                        isColMax = false;
                    }
                }
                if(isRowMin && isColMax) {
                    System.out.println((i + 1) + " " + (j + 1) + " " + a[i][j]);
                    found = true;
                    break outer;
                }
            }
        }
        if(!found) {
            System.out.println(-1);
        }
    }
}

