import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long[][] p = new long[n][n];
        for(int i = 0; i < n; i++) {
            for(int j = 0; j <= i; j++) {
                if(j == 0 || j == i) {
                    p[i][j] = 1;
                } else {
                    p[i][j] = p[i - 1][j - 1] + p[i - 1][j];
                }
            }
        }
        for(int i = 0; i < n; i++) {
            for(int j = 0; j <= i; j++) {
                if(j > 0) {
                    System.out.print(" ");
                }
                System.out.print(p[i][j]);
            }
            System.out.println();
        }
    }
}
